import{_ as i,o as t,c as a,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Lab 1 · Shipping your first change","description":"","frontmatter":{},"headers":[],"relativePath":"labs/lab-1-shipping-your-first-change.md","filePath":"labs/lab-1-shipping-your-first-change.md","lastUpdated":null}'),n={name:"labs/lab-1-shipping-your-first-change.md"};function o(r,e,h,l,d,c){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="lab-1-·-shipping-your-first-change" tabindex="-1">Lab 1 · Shipping your first change <a class="header-anchor" href="#lab-1-·-shipping-your-first-change" aria-label="Permalink to &quot;Lab 1 · Shipping your first change&quot;">​</a></h1><p><strong>Deliverable:</strong> one merged pull request · <strong>Time:</strong> two hours</p><p>Your first week on any team is not spent writing clever code. It is spent getting the project running, reading enough of it to find where a change belongs, and landing something small without breaking anything. That is this lab.</p><h2 id="setup-do-this-before-the-session-if-you-can" tabindex="-1">Setup (do this before the session if you can) <a class="header-anchor" href="#setup-do-this-before-the-session-if-you-can" aria-label="Permalink to &quot;Setup (do this before the session if you can)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">k</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> didlab-trustville/contracts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> foundry-rs/forge-std</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OpenZeppelin/openzeppelin-contracts@v5.0.2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local</span></span></code></pre></div><p>You should have a private Trustville on localhost with 22 contracts deployed. Import the anvil account the script prints, add the network to MetaMask, and complete the onboarding steps in the UI. <strong>If this does not work, nothing else in the course does</strong> — fix it first and write the incident up if it took real effort.</p><h2 id="the-job" tabindex="-1">The job <a class="header-anchor" href="#the-job" aria-label="Permalink to &quot;The job&quot;">​</a></h2><p>Two changes to the onboarding and Town Hall areas.</p><h3 id="_1-the-network-name-is-a-lie" tabindex="-1">1. The network name is a lie <a class="header-anchor" href="#_1-the-network-name-is-a-lie" aria-label="Permalink to &quot;1. The network name is a lie&quot;">​</a></h3><p><code>Onboarding.jsx</code> tells every user to &quot;Switch to the DIDLab network&quot;. Run against a local chain and it still says DIDLab, while the wallet is being asked to add <em>Local Trustville</em>.</p><p>Fix it so every user-visible mention of the network reads from the configured chain rather than a literal. <code>app/src/chain.js</code> already knows the name.</p><p>Hardcoded strings that duplicate configuration are one of the most common sources of &quot;works in dev, wrong in prod&quot;. Find them all — there is more than one.</p><h3 id="_2-let-a-resident-verify-their-own-credential-hash" tabindex="-1">2. Let a resident verify their own credential hash <a class="header-anchor" href="#_2-let-a-resident-verify-their-own-credential-hash" aria-label="Permalink to &quot;2. Let a resident verify their own credential hash&quot;">​</a></h3><p>Module 1 stores a hash of a credential document, never the document. Nothing in the UI lets anyone check that the hash corresponds to what they hold.</p><p>Add to the Town Hall card, for a connected resident:</p><ul><li>their stored <code>credentialHash</code>, readable and copyable;</li><li>an input where they paste their credential text;</li><li>an immediate verdict: does it hash to the stored value or not.</li></ul><p>The check happens <strong>in the browser</strong>. No transaction, no RPC call, no data leaving the page. If it sends anything anywhere you have misunderstood the point of the feature.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>[ ] No user-visible string names a network that configuration did not supply.</li><li>[ ] Running against a local chain, every network mention says the local chain&#39;s name.</li><li>[ ] A registered resident sees their stored hash.</li><li>[ ] Pasting the correct text shows a clear match; anything else shows a clear mismatch.</li><li>[ ] A connected but <strong>unregistered</strong> address sees something sensible, not a crash and not a hash of zeros.</li><li>[ ] A disconnected visitor sees the card without errors in the console.</li><li>[ ] Verification performs no network request. Prove it in the PR with a screenshot of the network tab, or by explaining why there is nothing to show.</li><li>[ ] <code>npm run build</code> succeeds and CI is green.</li></ul><h2 id="technical-requirements" tabindex="-1">Technical requirements <a class="header-anchor" href="#technical-requirements" aria-label="Permalink to &quot;Technical requirements&quot;">​</a></h2><ul><li>Use <code>keccak256</code> and <code>stringToHex</code> from viem. Match exactly what <code>TownHall.jsx</code> does when it registers — if the two disagree, a correct document will fail to verify, and that is the bug students most often ship here.</li><li>Follow the existing component patterns. Read <code>TownHall.jsx</code> and <code>Housing.jsx</code> first.</li><li>No new dependencies.</li></ul><h2 id="how-your-pr-will-be-reviewed" tabindex="-1">How your PR will be reviewed <a class="header-anchor" href="#how-your-pr-will-be-reviewed" aria-label="Permalink to &quot;How your PR will be reviewed&quot;">​</a></h2><p>A reviewer will check out your branch, run it against a local chain, and try to break the feature: empty input, whitespace, a trailing newline, an address that never registered, a wallet disconnected mid-use.</p><p>They will also read your description. &quot;Fixed the network name and added hash verification&quot; is not a description — the diff says that. Tell them why you put the component where you did, and what you decided about whitespace.</p><h2 id="common-ways-this-goes-wrong" tabindex="-1">Common ways this goes wrong <a class="header-anchor" href="#common-ways-this-goes-wrong" aria-label="Permalink to &quot;Common ways this goes wrong&quot;">​</a></h2><ul><li><strong>Trailing newline.</strong> Paste from a text file and you get <code>\\n</code> on the end, so the hash differs and the student concludes the feature is broken. Decide deliberately whether to trim, then document the decision.</li><li><strong>Hashing the wrong thing.</strong> Registration hashes a specific string. If you hash something else, verification always fails for honest users.</li><li><strong>Rendering before the read resolves.</strong> <code>credentialHash</code> is undefined for a moment. Undefined is not &quot;no match&quot;, it is &quot;not known yet&quot;, and they should look different.</li><li><strong>A crash for a disconnected visitor.</strong> Most of the site is readable without a wallet. Keep it that way.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>Do not change the contracts. Do not restyle the site. Do not fix unrelated things you find — note them in the PR description instead, which is what a professional does with a bug they were not sent to fix.</p><h2 id="hand-in" tabindex="-1">Hand in <a class="header-anchor" href="#hand-in" aria-label="Permalink to &quot;Hand in&quot;">​</a></h2><ol><li>The PR, CI green, reviewed and approved by a classmate.</li><li>Your review of someone else&#39;s PR.</li><li>An incident write-up if anything broke — setup counts.</li></ol>`,30)])])}const g=i(n,[["render",o]]);export{u as __pageData,g as default};
